net.coobird.thumbnailator.filters.ImageFilter filter1 = new net.coobird.thumbnailator.filters.ImageFilter() {
    public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
        return new java.awt.image.BufferedImage(img.getWidth() + 10, img.getHeight(), java.awt.image.BufferedImage.TYPE_INT_ARGB);
    }
};

net.coobird.thumbnailator.filters.ImageFilter filter2 = new net.coobird.thumbnailator.filters.ImageFilter() {
    public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
        return new java.awt.image.BufferedImage(img.getWidth(), img.getHeight() + 20, java.awt.image.BufferedImage.TYPE_INT_ARGB);
    }
};

net.coobird.thumbnailator.filters.Pipeline pipeline = new net.coobird.thumbnailator.filters.Pipeline();
pipeline.addAll(java.util.Arrays.asList(filter1, filter2));

java.awt.image.BufferedImage result = pipeline.apply(sourceImage);

assert result.getWidth() == sourceImage.getWidth() + 10 : "Width not updated correctly by first filter";
assert result.getHeight() == sourceImage.getHeight() + 20 : "Height not updated correctly by second filter";

System.out.println("__CHECK__ addAll " + (result.getWidth() - sourceImage.getWidth()) + "x" + (result.getHeight() - sourceImage.getHeight()));
